import {illustration} from './illustrations.mjs';
import {fixture as f,money as m,total,estimatedDate,parseCurrency} from './model.mjs';
import {transactions,filterTransactions,recurring,recurringTotal,reviewTotal,categories,insights,goalScenario} from './ecosystem-model.mjs';

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const a=(text,route,cls='text-btn')=>`<a class="${cls}" href="#/${route}">${text}</a>`;
const money=n=>(n>0?'+':'')+m(n);
const date=d=>new Intl.DateTimeFormat('en-IN',{month:'short',day:'2-digit',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T00:00:00Z'));
const row=(name,value)=>`<div class="row"><span>${name}</span><strong class="num">${value}</strong></div>`;
const progress=(name,saved,target)=>{const percent=Math.round(saved/target*100);return `<div class="progress" role="img" aria-label="${name}: ${percent}% saved, ${m(saved)} of ${m(target)}"><span style="width:${percent}%"></span></div><p class="muted">${percent}% saved</p>`;};

const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',transactions:'<path d="M4 7h16M4 17h16m-4-14 4 4-4 4M8 13l-4 4 4 4"/>',goals:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><path d="m12 12 8-8"/>',insights:'<path d="M4 20V10m8 10V4m8 16v-7"/>'};
export function navigation(route,mobile=false){let active=route.split('/')[0];if(['purchase','scenario','preview'].includes(active))active='home';if(active==='recurring')active='transactions';return `<nav class="${mobile?'bottom-nav':'desktop-nav'}" aria-label="${mobile?'Mobile':'Primary'} navigation">${['home','transactions','goals','insights'].map(id=>`<a href="#/${id}" ${active===id?'aria-current="page"':''}>${mobile?`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6">${icons[id]}</svg>`:''}<span>${id[0].toUpperCase()+id.slice(1)}</span></a>`).join('')}</nav>`;}

export function createEcosystem({getPlan,useContribution,getSaved=()=>f.goalSaved,brand}){
  let query='';let filter='all';let goalAmount=10000;
  const notice=()=>{const p=getPlan();return p.previous?`<div class="notice"><div><strong>Current plan: ${m(p.contribution)} for Goa</strong><p>Estimated completion ${esc(p.date)}. Planning only; no money moved.</p></div><button type="button" class="text-btn" data-action="undo">Undo</button></div>`:'';};
  const heading=(eyebrow,title,description,action='')=>`<div class="page-heading ecosystem-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${action}</div>`;
  const main=content=>`<main tabindex="-1" id="main" class="ecosystem-page fade">${content}</main>`;
  const scopeNote=()=>`<p class="data-note">A sample of completed activity, not a full ledger. Your ₹42,800 balance is the current snapshot; these entries are not deducted again.</p>`;
  const txRows=items=>`<ul class="transaction-list">${items.map(t=>`<li><a class="transaction-row" href="#/transactions/${t.id}"><span class="category-icon" aria-hidden="true">${t.kind==='income'?'＋':t.category==='Transport'?'↗':t.kind==='bills'?'↻':'·'}</span><span class="transaction-name"><strong>${esc(t.merchant)}</strong><small>${esc(t.category)}</small></span><span class="transaction-amount num ${t.amount>0?'income':''}">${money(t.amount)}</span><span class="row-chevron" aria-hidden="true">›</span></a></li>`).join('')}</ul>`;
  function txResults(){const items=filterTransactions(query,filter);const groups=[...new Set(items.map(t=>t.date))];return items.length?groups.map(d=>`<section class="date-group"><h2>${date(d)}</h2>${txRows(items.filter(t=>t.date===d))}</section>`).join(''):`<div class="empty-state">${illustration('receipt')}<h2>Nothing here matches those filters.</h2><p>Try a merchant name or a different activity filter.</p><button type="button" class="text-btn" data-action="clear-transactions">Clear search and filters</button></div>`;}
  function transactionsPage(){return main(heading('Actual activity','Transactions','Where your money has been going.',a('Recurring payments','recurring','btn secondary'))+`<section aria-label="Transaction filters"><label for="transaction-search" class="search-label">Search transactions</label><input id="transaction-search" type="search" value="${esc(query)}" placeholder="Search merchant or category" autocomplete="off"><div class="filter-row" role="group" aria-label="Activity type">${['all','income','spending','bills'].map(id=>`<button type="button" class="filter-chip" data-filter="${id}" aria-pressed="${filter===id}">${id[0].toUpperCase()+id.slice(1)}</button>`).join('')}<span id="transaction-count" class="muted" role="status">${filterTransactions(query,filter).length} ${filterTransactions(query,filter).length===1?'transaction':'transactions'}</span></div></section><div id="transaction-results">${txResults()}</div>${scopeNote()}`);}
  function missing(back){return main(`${a('Back',back,'back')}<div class="flow-header"><h1>That item isn’t in this demo.</h1><p>Return to the overview to choose a sample item.</p></div>`);}
  function transactionDetail(id){const t=transactions.find(t=>t.id===id);if(!t)return missing('transactions');return main(`<div class="detail-page">${a('← Transactions','transactions','back')}${heading('Completed activity',esc(t.merchant),'')}<div class="detail-amount num ${t.amount>0?'income':''}">${money(t.amount)}</div><p>${date(t.date)}${t.time?' · '+t.time:''}</p><dl class="detail-facts"><div><dt>Category</dt><dd>${esc(t.category)}</dd></div><div><dt>Payment account</dt><dd>Account •• 2481</dd></div><div><dt>Status</dt><dd><span class="tag">✓ Completed</span></dd></div></dl><div class="explanation">This is recorded activity. Hypothetical purchases explored in ELSE never appear in this list.</div>${t.id==='netflix'||t.id==='cult-fit'?`<div class="section">${a('View recurring reference','recurring/'+t.id)}</div>`:''}${scopeNote()}</div>`);}
  function goalsPage(){const p=getPlan();return main(heading('Goals','Plans your money is<br>making possible.','Saving has a place in your month, alongside everything else.')+notice()+`<div class="goals-grid"><section class="goal-panel"><div class="section-title"><h2>Goa</h2><span class="muted">Shared goal</span></div>${brand.badge()}<div class="goal-number num">${m(getSaved())} <small>of ${m(f.goalTarget)}</small></div>${progress('Goa',getSaved(),f.goalTarget)}${row('Planned this month',m(p.contribution))}${row('Estimated completion',esc(p.date))}<div class="goal-actions">${a('View Goa goal','goals/goa','btn secondary')}${a('What if I save more?','goals/goa/scenario')}</div></section><section class="goal-panel"><div class="section-title"><h2>Emergency fund</h2><span class="tag">✓ Protected</span></div><div class="goal-number num">${m(f.emergency)} <small>of ${m(f.emergencyTarget)}</small></div>${progress('Emergency fund',f.emergency,f.emergencyTarget)}<p class="goal-protection">Excluded from ordinary purchase-adjustment suggestions. Its balance stays separate from your ₹42,800 available balance.</p><div class="goal-actions">${a('View protected goal','goals/emergency','btn secondary')}</div></section></div><div class="connected-note"><h2>One plan, wherever you look.</h2><p>The October Goa contribution here is the same plan used on Home and in purchase scenarios.</p>${a('Explore a purchase','purchase')}</div>`);}
  function goaDetail(){const p=getPlan();const remaining=Math.max(0,f.goalTarget-getSaved()-p.contribution);return main(`<div class="detail-page">${a('← All goals','goals','back')}${heading('Savings goal','Goa','A goal with room for the rest of your month.')}${notice()}${brand.badge()}<div class="detail-amount num">${m(getSaved())} <small>of ${m(f.goalTarget)}</small></div>${progress('Goa',getSaved(),f.goalTarget)}${brand.contributions(brand.publicSnapshot())}<dl class="detail-facts"><div><dt>Remaining to target</dt><dd class="num">${m(f.goalTarget-getSaved())}</dd></div><div><dt>October planned contribution</dt><dd class="num">${m(p.contribution)}</dd></div><div><dt>Estimated completion</dt><dd>${esc(p.date)}, 2026</dd></div></dl><section class="timeline-section"><h2>How the current plan adds up</h2><ol class="contribution-timeline"><li><span>Already saved</span><strong class="num">${m(getSaved())}</strong></li><li><span>October <small>Planned contribution</small></span><strong class="num">+${m(p.contribution)}</strong></li><li><span>${p.date==='Oct 30'?'Additional contribution':'November'} <small>${p.date==='Oct 30'?'Needed by the illustrative completion date':'Estimated amount still needed'}</small></span><strong class="num">+${m(remaining)}</strong></li><li><span>Goal target</span><strong class="num">${m(f.goalTarget)}</strong></li></ol><p class="muted">${p.date==='Oct 30'?'Oct 30 assumes the remaining '+m(remaining)+' is also added by that date. ':''}Dates are illustrative estimates, not forecasts or scheduled transfers.</p></section><div class="actions section">${a('What if I save more?','goals/goa/scenario','btn blue')}${a('View your month','home','btn secondary')}</div>${brand.detailExtras()}</div>`);}
  function emergencyDetail(){return main(`<div class="detail-page">${a('← All goals','goals','back')}${heading('Protected savings','Emergency fund','A separate reserve, outside everyday purchase scenarios.')}<span class="tag">✓ Protected</span><div class="detail-amount num">${m(f.emergency)} <small>of ${m(f.emergencyTarget)}</small></div>${progress('Emergency fund',f.emergency,f.emergencyTarget)}${row('Remaining to target',m(f.emergencyTarget-f.emergency))}<div class="protected-line section"><h2>What protection means</h2><p>Protected goals are excluded from ordinary purchase-adjustment suggestions.</p></div><div class="explanation">The ₹96,000 saved here is not part of the ₹42,800 available balance. Changing Goa’s plan or exploring a phone purchase leaves this reserve untouched.</div></div>`);}
  function goalResult(){const p=getPlan();let s;try{s=goalScenario(goalAmount,p.contribution,getSaved());}catch{return `<p class="muted">Enter a valid contribution to see what changes.</p>`;}return `<div class="goal-plan-comparison"><section><div class="eyebrow">Current plan</div><div class="goal-number num">${m(p.contribution)}</div><p class="muted">Estimated ${esc(p.date)}</p></section><section><div class="eyebrow">Scenario only</div><div class="goal-number num">${m(s.contribution)}</div><p class="muted">Estimated ${esc(s.date)}</p></section></div><section class="goal-impact"><h2>What else changes</h2>${row('Monthly flexibility change',money(s.flexibilityChange))}${row('Flexible before goals',m(f.balance-total))}${row('After this Goa contribution',m(s.remainder))}${row('Preferred buffer',m(f.buffer))}<div class="tradeoff"><div><h3>${s.bufferGap?'Below your preferred buffer':'Room above your preferred buffer'}</h3><p>${s.bufferGap?`After allocating ${m(s.contribution)} to Goa, ${m(s.remainder)} remains. That is ${m(s.bufferGap)} below the buffer you prefer.`:`After allocating ${m(s.contribution)} to Goa, ${m(s.remainder)} remains — ${m(s.aboveBuffer)} above your buffer preference.`}</p></div><strong class="num">${s.bufferGap?'−'+m(s.bufferGap):m(s.aboveBuffer)}</strong></div><div class="explanation">${p.contribution===8000&&s.contribution===10000?'The illustrative date moves 9 days earlier, from Nov 08 to Oct 30, while monthly flexibility is ₹2,000 lower. ':''}The ${esc(s.date)} estimate${s.contribution===10000?' assumes another '+m(s.remainingGoal)+' is added by Oct 30':''}. ${m(s.remainingGoal)} would still be needed after this contribution. No transfer is scheduled.</div></section><div class="decision"><div class="actions"><button class="btn secondary" type="button" data-action="use-goal-contribution">Use this contribution</button><button class="btn secondary" type="button" data-action="keep-goal-plan">Keep current plan</button></div><p>Nothing is applied automatically. Your protected money and commitments stay unchanged.</p></div>`;}
  function goalScenarioPage(){return main(`<div class="goal-scenario-page">${a('← Goa goal','goals/goa','back')}${heading('Goal scenario','If you save more,<br>what else changes?','Compare a contribution with your current plan before deciding.')}<div class="goal-scenario-grid"><form id="goal-scenario-form" class="goal-scenario-input" novalidate><span class="preview-tag">SCENARIO</span><label for="goal-contribution">Try an October contribution</label><div class="input-money"><span>₹</span><input id="goal-contribution" name="goal-contribution" inputmode="numeric" type="text" value="${goalAmount}" aria-describedby="goal-error goal-input-help"></div><div id="goal-error" class="error" role="status"></div><p id="goal-input-help" class="muted">An allocation from the same ₹16,100 flexible money. Your accepted plan hasn’t changed.</p><button class="btn secondary" type="submit">Check contribution</button></form><div id="goal-scenario-result" aria-live="polite" aria-atomic="true">${goalResult()}</div></div></div>`);}
  function recurringPage(review=false){const items=review?recurring.filter(r=>r.review):recurring;return main(`${a('← Transactions','transactions','back')}${heading('Recurring payments',review?'A few subscriptions<br>worth a look.':'Repeats every month.','Predictable outflow, with its effect on your month in view.')}<section class="recurring-summary"><div><div class="eyebrow">${review?'Review subset':'Full monthly reference'}</div><div class="detail-amount num">${m(review?reviewTotal:recurringTotal)} <small>/ month</small></div><p>${review?'Netflix, Spotify and iCloud. You choose what to keep.':'Six recurring items · Utility and lifestyle'}</p></div>${review?a('View all recurring payments','recurring','btn secondary'):a('Review ₹843 / month','recurring/review','btn secondary')}</section>${['Utility','Lifestyle'].filter(g=>items.some(r=>r.group===g)).map(g=>`<section class="recurring-group"><div class="section-title"><h2>${g==='Utility'?'Essential / utility':'Subscription / lifestyle'}</h2><span class="num muted">${m(items.filter(r=>r.group===g).reduce((sum,r)=>sum+r.amount,0))} / month</span></div><ul class="transaction-list">${items.filter(r=>r.group===g).map(r=>`<li><a class="transaction-row" href="#/recurring/${r.id}"><span class="category-icon" aria-hidden="true">↻</span><span class="transaction-name"><strong>${r.name}</strong><small>${r.category} · Monthly</small></span><span class="transaction-amount num">${m(r.amount)}</span><span class="row-chevron" aria-hidden="true">›</span></a></li>`).join('')}</ul></section>`).join('')}<div class="explanation"><strong>Full cycle and remaining commitments are different views.</strong> This ₹3,942 reference schedule is not reconciled to the ₹26,700 remaining commitment snapshot, so it is not deducted again. Dates and payment history are illustrative. Reviewing an item does not cancel it.</div>`);}
  function recurringDetail(id){const r=recurring.find(r=>r.id===id);if(!r)return missing('recurring');return main(`<div class="detail-page">${a('← Recurring payments','recurring','back')}${heading('Recurring reference',r.name,'Monthly · '+r.category)}<div class="detail-amount num">${m(r.amount)} <small>/ month</small></div><dl class="detail-facts"><div><dt>Next expected · illustrative</dt><dd>${r.next}, 2026</dd></div><div><dt>Category</dt><dd>${r.category}</dd></div><div><dt>Annual equivalent</dt><dd class="num">${m(r.amount*12)}</dd></div></dl><section class="section"><h2>Last three payments</h2><p class="muted">Illustrative recurring history, separate from the sample transaction list.</p><ol class="payment-history">${['Most recent','Previous','Earlier'].map(label=>`<li><span>${label}</span><strong class="num">${m(r.amount)}</strong></li>`).join('')}</ol></section><div class="tradeoff"><div><h2>If this recurring payment stopped</h2><p>Your monthly flexible money would increase by ${m(r.amount)} in a future month where this payment was otherwise due. The current ₹16,100 snapshot does not change.</p></div></div><p class="data-note">This is an informational comparison. ELSE does not execute payments or cancel subscriptions.</p></div>`);}
  function categoryChart(){return `<ul class="category-chart" aria-label="October spending composition, total ₹38,400">${[...categories].sort((a,b)=>b.amount-a.amount).map(c=>`<li><a class="chart-category" href="#/insights/category/${c.id}"><span class="chart-label"><strong>${c.name}</strong><span class="num">${m(c.amount)} <small>${(c.amount/insights.spent*100).toFixed(1)}%</small></span></span><span class="chart-track" aria-hidden="true"><span style="width:${c.amount/Math.max(...categories.map(category=>category.amount))*100}%;background:${c.color}"></span></span></a></li>`).join('')}</ul>`;}
  function insightsPage(){const difference=insights.spent-insights.previous;const percent=(difference/insights.previous*100).toFixed(1);const p=getPlan();return main(`${heading('Monthly insights','Your month, in context.','October 2026 · Snapshot at Oct 03')}<section class="insight-hero"><div><div class="eyebrow">Spent so far · Oct 01–03</div><div class="detail-amount num">${m(insights.spent)}</div><p>Same point last month: ${m(insights.previous)}</p></div><div class="comparison-context"><strong class="num">+${m(difference)} <span>+${percent}%</span></strong><p>Oct 01–03 compared with Sep 01–03, 2026.<br>A change in pace, without a judgment.</p></div></section><div class="insights-grid"><section><div class="section-title"><h2>Where spending sits</h2><span class="muted">${m(insights.spent)} total</span></div>${categoryChart()}<p class="data-note">Bars compare category amounts. Labels show their shares of the total. This summary includes activity beyond the nine sample transactions; it is not recalculated from that list.</p></section><aside class="insight-observations"><section><div class="eyebrow">Food & dining</div><h2>${m(1850)} higher</h2><p>Than the ₹7,600 reference at the same point last month.</p>${a('Explore this category','insights/category/food')}</section><section><div class="eyebrow">Transport</div><h2>${m(620)} lower</h2><p>Than the ₹4,870 comparable period last month.</p>${a('Explore this category','insights/category/transport')}</section><section><div class="eyebrow">Recurring subscriptions</div><h2>${m(reviewTotal)} / month</h2><p>Across Netflix, Spotify and iCloud. These subscriptions may be worth reviewing.</p>${a('View recurring payments','recurring/review')}</section></aside></div><div class="connected-note"><h2>The goal plan alongside your spending</h2><p>Goa has ${m(p.contribution)} planned this October, with estimated completion ${esc(p.date)}. Changing a planned contribution doesn’t rewrite actual spending.</p>${a('View Goa goal','goals/goa')}</div>`);}
  function categoryDetail(id){const c=categories.find(c=>c.id===id);if(!c)return missing('insights');const samples=transactions.filter(t=>t.date.startsWith('2026-10')&&t.amount<0&&(c.id==='food'?t.category==='Food & dining':c.id==='transport'?t.category==='Transport':c.id==='shopping'?t.category==='Shopping':c.id==='lifestyle'?t.category==='Subscription':false));return main(`<div class="detail-page">${a('← Monthly insights','insights','back')}${heading('Category breakdown',c.name,'Oct 01–03, 2026 · Summary snapshot')}<div class="detail-amount num">${m(c.amount)}</div><p>${(c.amount/insights.spent*100).toFixed(1)}% of ${m(insights.spent)} spent so far.</p>${c.reference?`<dl class="detail-facts"><div><dt>Sep 01–03 comparable amount</dt><dd class="num">${m(c.reference)}</dd></div><div><dt>Difference</dt><dd class="num">${money(c.amount-c.reference)}</dd></div></dl>`:''}<section class="section"><h2>Related sample activity</h2>${samples.length?txRows(samples):'<p class="muted">This category has no entries in the small sample transaction list.</p>'}<p class="data-note">These sample entries do not add up to the full category total. Summary figures are a separate fixed snapshot, not a complete transaction ledger.</p></section>${c.id==='lifestyle'?a('View recurring payments','recurring','btn secondary'):a('View all transactions','transactions','btn secondary')}</div>`);}
  function screen(route){if(route==='transactions')return transactionsPage();if(route.startsWith('transactions/'))return transactionDetail(route.split('/')[1]);if(route==='goals')return goalsPage();if(route==='goals/goa')return goaDetail();if(route==='goals/goa/scenario')return goalScenarioPage();if(route==='goals/emergency')return emergencyDetail();if(route==='recurring'||route==='recurring/review')return recurringPage(route.endsWith('/review'));if(route.startsWith('recurring/'))return recurringDetail(route.split('/')[1]);if(route==='insights')return insightsPage();if(route.startsWith('insights/category/'))return categoryDetail(route.split('/')[2]);return null;}
  function updateTransactions(){const result=document.querySelector('#transaction-results');if(!result)return;result.innerHTML=txResults();document.querySelector('#transaction-count').textContent=`${filterTransactions(query,filter).length} ${filterTransactions(query,filter).length===1?'transaction':'transactions'}`;for(const b of document.querySelectorAll('[data-filter]'))b.setAttribute('aria-pressed',String(b.dataset.filter===filter));}
  function updateGoal(){const input=document.querySelector('#goal-contribution');if(!input)return;goalAmount=parseCurrency(input.value);let error='';try{goalScenario(goalAmount,getPlan().contribution,getSaved());}catch{error='Enter an amount greater than ₹0.';}input.setAttribute('aria-invalid',String(!!error));document.querySelector('#goal-error').textContent=error;document.querySelector('#goal-scenario-result').innerHTML=goalResult();}
  function click(e){const el=e.target.closest('[data-filter],[data-action]');if(!el)return false;if(el.dataset.filter){filter=el.dataset.filter;updateTransactions();return true;}if(el.dataset.action==='clear-transactions'){query='';filter='all';document.querySelector('#transaction-search').value='';updateTransactions();document.querySelector('#transaction-search').focus();return true;}if(el.dataset.action==='use-goal-contribution'){try{goalScenario(goalAmount,getPlan().contribution);}catch{updateGoal();return true;}useContribution(goalAmount);return true;}if(el.dataset.action==='keep-goal-plan'){location.hash='/goals/goa';document.querySelector('#status').textContent='No changes made. Your current goal plan is unchanged.';return true;}return false;}
  function input(e){if(e.target.id==='transaction-search'){query=e.target.value;updateTransactions();}if(e.target.id==='goal-contribution')updateGoal();}
  function submit(e){if(e.target.id==='goal-scenario-form'){e.preventDefault();updateGoal();return true;}return false;}
  function homeEntries(){return `<section class="home-activity"><div class="section-title"><h2>Recent activity</h2>${a('See all transactions','transactions')}</div>${txRows(transactions.slice(0,3))}</section><div class="home-related"><span>${a('See all goals','goals')}</span><span>${a('View monthly insights','insights')}</span><span>${a('Recurring payments','recurring')}</span></div>`;}
  return {screen,click,input,submit,homeEntries};
}
